css:
@keyframes fxhud-a{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}@keyframes fxhud-b{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
.fx-hud{width:min(940px,100%);display:grid;gap:3em;text-align:center;justify-items:center}
.fx-hud .eye{font-size:.78em;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--accent)}
.fx-hud h1{font-size:clamp(2.4em,6.4vw,4.8em);line-height:1.12;max-width:13em}
.fx-hud .u{position:relative;display:inline-block;white-space:nowrap}
.fx-hud .u svg{position:absolute;left:-2%;width:104%;overflow:visible;pointer-events:none;fill:none;stroke:currentColor;stroke-linecap:round;stroke-linejoin:round}
.fx-hud .u path{stroke-dasharray:1;stroke-dashoffset:1;animation:fxhud-a calc(1.1s/var(--speed)) cubic-bezier(.6,.1,.2,1) .5s forwards}
.fx-hud .u:hover path{animation-name:fxhud-b}
.fx-hud .wavy{color:var(--accent)}.fx-hud .wavy svg{bottom:-.2em;height:.28em}.fx-hud .wavy path{stroke-width:5;vector-effect:non-scaling-stroke}
.fx-hud .row{display:grid;grid-template-columns:1fr 1fr;gap:2.4em;width:100%}
.fx-hud h2{font-size:clamp(1.6em,3.4vw,2.4em);line-height:1.25}
.fx-hud .line{color:var(--primary)}.fx-hud .line svg{bottom:-.1em;height:.2em}.fx-hud .line path{stroke-width:3;vector-effect:non-scaling-stroke}
.fx-hud .line svg+svg{bottom:-.3em}.fx-hud .line svg+svg path{animation-delay:.9s}
.fx-hud .ring{color:var(--accent);padding:0 .25em}.fx-hud .ring svg{top:-.2em;left:-8%;width:116%;height:1.5em}.fx-hud .ring path{stroke-width:2.5;vector-effect:non-scaling-stroke;animation-delay:1.2s}
.fx-hud small{opacity:.5;font-size:.85em}
@media(max-width:700px){.fx-hud .row{grid-template-columns:1fr;gap:2em}.fx-hud .u{white-space:normal}}
@media(prefers-reduced-motion:reduce){.fx-hud .u path{animation:none;stroke-dashoffset:0}}
/* touch: :hover mirrored as .is-tap */
.fx-hud .u.is-tap path{animation-name:fxhud-b}
